// <auto-generated> by cs/tools/ts2cs.mjs from src/sim/power.ts, then fixed by hand where it says so.
// Power and spoilage.
//
// A generator burns wood (haulers keep it fuelled, up to FUEL_MAX: jobs.ts)
// and powers everything within POWER_RADIUS. It runs while there's fuel and
// something to power, burning one wood every FUEL_TICKS (furniture.loot
// counts the ticks), and it's noisy (once an hour). Lamps light up at night
// when powered: night zombies don't arrive within LAMP_DETER of a lit lamp
// (zombies.ts), and guards fight better in the light. A powered fridge keeps
// the food round it from spoiling. While the mains are on (timeline.ts), iceboxes are fridges
// and indoors is lit at night.
//
// Spoilage (harsh games only): food and hot meals age (item.wear) and rot
// at FOOD_SHELF and MEAL_SHELF. They age twice as fast in summer, not at all
// in winter, half as fast in a complete storage room, and not near a powered
// fridge.
#nullable disable warnings
namespace LoonieRoo.Sim;

public static partial class Power
{
    static Power()
    {
        Time.onClock(() => FUEL_TICKS = 2 * Time.TICKS_PER_HOUR);
        Time.onClock(() => HEATER_FUEL_TICKS = 3 * Time.TICKS_PER_HOUR);
        Time.onClock(() =>
        {
            FOOD_SHELF = 4 * Time.DAY_LENGTH;
            MEAL_SHELF = Time.DAY_LENGTH;
        });
    }

    public const int POWER_RADIUS = 12;

    public const int FUEL_MAX = 4;

    public static double FUEL_TICKS = 2 * Time.TICKS_PER_HOUR;

    public const int LAMP_DETER = 16;

    /// <summary>Lamps light this far; guards in it hit harder.</summary>
    public const int LAMP_LIGHT = 4;

    public const int LIGHT_DAMAGE_PCT = 125;

    public const int FRIDGE_RADIUS = 2;

    /// <summary>Heaters (braziers): keep anyone within HEAT_RADIUS from the cold, burning a wood every HEATER_FUEL_TICKS on cold nights.</summary>
    public const int HEAT_RADIUS = 4;

    public static double HEATER_FUEL_TICKS = 3 * Time.TICKS_PER_HOUR;

    /// <summary>Chance per hour of burning that a heater sets its own tile alight.</summary>
    public const double HEATER_FIRE_CHANCE = 0.01;

    public const int SPOIL_CHECK_EVERY = 100;

    public static double FOOD_SHELF = 4 * Time.DAY_LENGTH;

    public static double MEAL_SHELF = Time.DAY_LENGTH;

    public static readonly List<string> CONSUMERS = ["lamp", "fridge", "radio", "lab", "beacon"];

    public static List<Furniture> generators(SimState state)
    {
        return FurnitureMod.ofKind(state, "generator");
    }

    /// <summary>Is a generator with fuel within reach of this point?</summary>
    public static bool isPowered(SimState state, Point p)
    {
        return generators(state).some((g) => g.stored > 0 && Space.manhattan(g, p) <= POWER_RADIUS);
    }

    /// <summary>Lamps that are lit right now.</summary>
    public static List<Furniture> litLamps(SimState state)
    {
        if (!Js.T(Time.isNight(state.tick)))
        {
            return [];
        }
        return FurnitureMod.ofKind(state, "lamp").filter((f) => Js.T(isPowered(state, f)));
    }

    public static bool inLight(SimState state, Point p)
    {
        return Js.T(TimelineMod.mainsLit(state, p)) || litLamps(state).some((l) => Space.manhattan(l, p) <= LAMP_LIGHT);
    }

    /// <summary>Generators burn fuel while they have something to power. Every tick.</summary>
    public static void updatePower(SimState state)
    {
        foreach (var g in Js.Iter(generators(state)))
        {
            if (g.stored == 0)
            {
                continue;
            }
            var load = CONSUMERS.some((kind) => kind != "lamp" || Js.T(Time.isNight(state.tick)) && FurnitureMod.ofKind(state, kind).some((f) => Space.manhattan(g, f) <= POWER_RADIUS));
            if (!Js.T(load))
            {
                continue;
            }
            g.loot += 1;
            if (state.tick % Time.TICKS_PER_HOUR == 0)
            {
                Noise.makeNoise(state, g, "generator");
            }
            if (g.loot < FUEL_TICKS)
            {
                continue;
            }
            g.loot = 0;
            g.stored -= 1;
            if (g.stored == 0)
            {
                g.storedKind = null;
                Events.logEvent(state, $"The generator at ({Js.Str(g.x)}, {Js.Str(g.y)}) ran out of fuel");
            }
        }
    }

    /// <summary>A lit heater within reach.</summary>
    public static bool isWarmed(SimState state, Point p)
    {
        return FurnitureMod.ofKind(state, "heater").some((f) => f.stored > 0 && Space.manhattan(f, p) <= HEAT_RADIUS);
    }

    /// <summary>Heaters burn on cold nights (winter, or a blizzard).</summary>
    public static void updateHeaters(SimState state)
    {
        var cold = Js.T(Time.isNight(state.tick)) && Seasons.seasonOf(state.tick) == "winter" || state.weather == "blizzard";
        if (!Js.T(cold))
        {
            return;
        }
        foreach (var h in Js.Iter([.. FurnitureMod.ofKind(state, "heater")]))
        {
            if (h.stored == 0)
            {
                continue;
            }
            h.loot += 1;
            if (h.loot % Time.TICKS_PER_HOUR == 0 && Hash.hashRoll(h.x, h.y, state.tick) < HEATER_FIRE_CHANCE && Js.T(FireMod.ignite(state, h.x, h.y)))
            {
                Events.logEvent(state, $"The heater at ({Js.Str(h.x)}, {Js.Str(h.y)}) set something alight!");
            }
            if (h.loot < HEATER_FUEL_TICKS)
            {
                continue;
            }
            h.loot = 0;
            h.stored -= 1;
            if (h.stored == 0)
            {
                h.storedKind = null;
            }
        }
    }

    /// <summary>Food and meals age, and rot. Harsh games only.</summary>
    public static void updateSpoilage(SimState state)
    {
        if (!Js.T(state.harsh) || state.tick % SPOIL_CHECK_EVERY != 0)
        {
            return;
        }
        var season = Seasons.seasonOf(state.tick);
        if (season == "winter")
        {
            return;
        }
        var rate = season == "summer" ? 2 : 1 + state.weather == "heatwave" ? 1 : 0;
        var stores = Rooms.completeRooms(state, "storage");
        var fridges = [.. FurnitureMod.ofKind(state, "fridge").filter((f) => Js.T(isPowered(state, f))), .. FurnitureMod.ofKind(state, "crate").filter((f) => Js.T(TimelineMod.isMainsFridge(state, f)))];
        var rotted = 0;
        foreach (var item in Js.Iter([.. state.items]))
        {
            if (item.kind != "food" && item.kind != "meal" || !Js.T(item.pos) || Js.T(item.reservedBy))
            {
                continue;
            }
            var p = item.pos;
            if (fridges.some((f) => Space.manhattan(f, p) <= FRIDGE_RADIUS))
            {
                continue;
            }
            item.wear += ((double)(SPOIL_CHECK_EVERY * rate) / (stores.has(Rooms.labelAt(state, p.x, p.y)) ? 2 : 1));
            if (item.wear < item.kind == "meal" ? MEAL_SHELF : FOOD_SHELF)
            {
                continue;
            }
            Items.removeItem(state, item);
            rotted += 1;
        }
        if (rotted > 0)
        {
            Events.logEvent(state, $"{Js.Str(rotted)} food {Js.Str(rotted == 1 ? "item" : "items")} rotted (cool storage, winter and fridges keep food)");
        }
    }
}
